const normaliseExtractedKey=key=>String(key||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const documentFieldAliases={fullname:'fullName',name:'fullName',legalname:'fullName',nationalid:'identityNumber',nationalidnumber:'identityNumber',identity:'identityNumber',identitynumber:'identityNumber',iqama:'identityNumber',iqamanumber:'identityNumber',mobile:'mobile',mobilenumber:'mobile',phone:'mobile',phonenumber:'mobile',dateofbirth:'dateOfBirth',dob:'dateOfBirth',birthdate:'dateOfBirth',gender:'gender',sex:'gender',email:'email',emailaddress:'email',city:'city',occupation:'occupation',profession:'occupation',salary:'monthlyIncome',monthlysalary:'monthlyIncome',monthlyincome:'monthlyIncome',income:'monthlyIncome',dependants:'dependants',dependents:'dependants',existingcover:'existingCover',coverage:'coverage',budget:'budget',term:'term'};
