 try{const json=JSON.parse(source);if(json&&typeof json==='object'&&!Array.isArray(json))for(const [key,value] of Object.entries(json)){const field=documentFieldAliases[normaliseExtractedKey(key)];if(field&&value!==undefined&&value!==null)extracted[field]=String(value).trim();}}catch{}
 for(const line of source.split(/[\r\n;|]+/)){const match=line.match(/^\s*([^:=]{2,40})\s*[:=]\s*(.+?)\s*$/);if(!match)continue;const field=documentFieldAliases[normaliseExtractedKey(match[1])];if(field&&!extracted[field])extracted[field]=match[2].trim();}
