 for(const form of [profileForm,purchaseForm].filter(Boolean)){const mobile=form.elements.mobile;if(mobile&&!mobile.value.includes('•')){mobile.setAttribute('pattern','05[0-9]{7}');mobile.setAttribute('minlength','9');mobile.setAttribute('maxlength','9');mobile.setAttribute('placeholder','05XXXXXXX');mobile.setAttribute('title','Enter 9 digits beginning with 05');}}
